#include <vector>
#include <cstring>
#include <cstdlib>
struct Indexed { int lod; uint16_t nstrips; const uint16_t* lengths; const uint16_t* const* strips; uint16_t count; const uint32_t* colors; const float *normals,*binormals,*tangents,*coords,*uv0,*uv1,*weights; const uint8_t* wind; };
struct Leaf { bool active; float alpha; int lod; uint16_t count; const uint8_t *maps,*clusters; const float *centers; const float *const* texcoords; const float *const* mapcoords; const uint32_t* colors; const float *normals,*binormals,*tangents,*weights; const uint8_t* wind; };
struct Billboard { bool active; const float *uv,*coords; float alpha; };
struct Geometry { Indexed branches; float alpha_branch; Indexed fronds; float alpha_frond; Leaf leaves[2]; Billboard billboards[3]; };
struct Textures { const char* branch; uint32_t leaf_count; const char*const* leaf; uint32_t frond_count; const char*const* frond; const char *composite,*shadow; };
#define METHOD __attribute__((thiscall))
using Ctor=void(METHOD*)(void*); using Dtor=void(METHOD*)(void*); using Load=bool(METHOD*)(void*,const unsigned char*,unsigned); using Compute=bool(METHOD*)(void*,const float*,unsigned,bool); using GetGeo=void(METHOD*)(void*,Geometry*,unsigned long,short,short,short); using GetTex=void(METHOD*)(void*,Textures*); using Lod=void(METHOD*)(void*,float); using GetBox=void(METHOD*)(void*,float*); using GetTable=const float*(METHOD*)(void*,unsigned*);
using GetSize=void(METHOD*)(void*,float*,float*); using SetSize=void(METHOD*)(void*,float,float); using EnumSet=void(METHOD*)(void*,int); using Camera=void(*)(const float*,const float*); using Auth=void(*)(const char*); using Flip=void(*)(bool); using Error=const char*(*)();
static FARPROC symbol(HMODULE h,const char* name){auto p=GetProcAddress(h,name);if(!p){fprintf(stderr,"missing export %s\n",name);exit(2);}return p;}
int main(int argc,char**argv){if(argc!=3){fprintf(stderr,"usage: speedtree-probe.exe <dll> <spt>\n");return 2;} HMODULE h=LoadLibraryA(argv[1]); if(!h){fprintf(stderr,"LoadLibrary failed %lu\n",GetLastError());return 2;}
#define GET(type,name) reinterpret_cast<type>(symbol(h,name))
 auto getsize=GET(GetSize,"?GetTreeSize@CSpeedTreeRT@@QBEXAAM0@Z"); auto setsize=GET(SetSize,"?SetTreeSize@CSpeedTreeRT@@QAEXMM@Z"); auto setbranch=GET(EnumSet,"?SetBranchLightingMethod@CSpeedTreeRT@@QAEXW4ELightingMethod@1@@Z"); auto setleaf=GET(EnumSet,"?SetLeafLightingMethod@CSpeedTreeRT@@QAEXW4ELightingMethod@1@@Z"); auto setfrond=GET(EnumSet,"?SetFrondLightingMethod@CSpeedTreeRT@@QAEXW4ELightingMethod@1@@Z"); auto windb=GET(EnumSet,"?SetBranchWindMethod@CSpeedTreeRT@@QAEXW4EWindMethod@1@@Z"); auto windl=GET(EnumSet,"?SetLeafWindMethod@CSpeedTreeRT@@QAEXW4EWindMethod@1@@Z"); auto windf=GET(EnumSet,"?SetFrondWindMethod@CSpeedTreeRT@@QAEXW4EWindMethod@1@@Z"); auto ctor=GET(Ctor,"??0CSpeedTreeRT@@QAE@XZ"); auto dtor=GET(Dtor,"??1CSpeedTreeRT@@QAE@XZ"); auto load=GET(Load,"?LoadTree@CSpeedTreeRT@@QAE_NPBEI@Z"); auto compute=GET(Compute,"?Compute@CSpeedTreeRT@@QAE_NPBMI_N@Z"); auto geo=GET(GetGeo,"?GetGeometry@CSpeedTreeRT@@QAEXAAUSGeometry@1@KFFF@Z"); auto tex=GET(GetTex,"?GetTextures@CSpeedTreeRT@@QBEXAAUSTextures@1@@Z"); auto lod=GET(Lod,"?SetLodLevel@CSpeedTreeRT@@QAEXM@Z"); auto bounds=GET(GetBox,"?GetBoundingBox@CSpeedTreeRT@@QBEXPAM@Z"); auto camera=GET(Camera,"?SetCamera@CSpeedTreeRT@@SAXPBM0@Z"); auto auth=GET(Auth,"?Authorize@CSpeedTreeRT@@SAXPBD@Z"); auto flip=GET(Flip,"?SetTextureFlip@CSpeedTreeRT@@SAX_N@Z"); auto error=GET(Error,"?GetCurrentError@CSpeedTreeRT@@SAPBDXZ"); auto table=GET(GetTable,"?GetLeafBillboardTable@CSpeedTreeRT@@QBEPBMAAI@Z");
 FILE*f=fopen(argv[2],"rb");if(!f){perror(argv[2]);return 2;} fseek(f,0,SEEK_END);long n=ftell(f);rewind(f); if(n<1||n>100000000){fprintf(stderr,"invalid spt size\n");return 2;}std::vector<unsigned char> data(n);if(fread(data.data(),1,n,f)!=(size_t)n)return 2;fclose(f);
 auth("");flip(true);float eye[3]={0,0,0},dir[3]={1,0,0};camera(eye,dir);alignas(16) unsigned char instance[8192]={};ctor(instance);if(!load(instance,data.data(),(unsigned)n)){fprintf(stderr,"LoadTree: %s\n",error());dtor(instance);return 1;}float size=0,variance=0; getsize(instance,&size,&variance); setbranch(instance,0);setleaf(instance,0);setfrond(instance,0);windb(instance,2);windl(instance,2);windf(instance,2);setsize(instance,size*0.3048f,0); printf("size %g variance %g scaled %g\n",size,variance,size*0.3048f); if(!compute(instance,nullptr,1,true)){fprintf(stderr,"Compute: %s\n",error());dtor(instance);return 1;}lod(instance,1.0f);Geometry g{};geo(instance,&g,0xffffffffu,-1,-1,-1);Textures t{};tex(instance,&t);float box[6];bounds(instance,box);unsigned nt=0;const float* b=table(instance,&nt);
 printf("box %g %g %g | %g %g %g\n",box[0],box[1],box[2],box[3],box[4],box[5]);printf("branches v%u strips%u ptr %p coords %p uv %p lod %d; fronds v%u strips%u; leaves %u active %d map %p centers %p table %u %p\n",g.branches.count,g.branches.nstrips,g.branches.strips,g.branches.coords,g.branches.uv0,g.branches.lod,g.fronds.count,g.fronds.nstrips,g.leaves[0].count,g.leaves[0].active,g.leaves[0].texcoords,g.leaves[0].centers,nt,b);printf("textures branch=%s composite=%s\n",t.branch?t.branch:"(null)",t.composite?t.composite:"(null)");if(g.branches.count&&g.branches.coords)printf("first branch coord %g %g %g\n",g.branches.coords[0],g.branches.coords[1],g.branches.coords[2]);dtor(instance);FreeLibrary(h);return 0;}
